'use strict';const {test}=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const {stage}=require('../scripts/stage-theme-dependencies.cjs');
test('stages new dependencies before their referencing templates and verifies bytes',async()=>{const remote=new Map();const client={async list(dir){return [...remote.keys()].filter(p=>p.startsWith(dir+'/')).map(p=>({name:p.slice(dir.length+1)}));},async uploadFrom(local,dest){remote.set(dest,fs.readFileSync(local));},async downloadTo(stream,dest){stream.end(remote.get(dest));}};const list=['static/css/product-commerce.css','snipplets/product/payment-summary.tpl'];assert.equal((await stage(client,process.cwd(),list)).length,2);assert.equal(remote.size,2);await stage(client,process.cwd(),list);remote.set('/'+list[0],Buffer.from('unexpected'));await assert.rejects(stage(client,process.cwd(),list),/existing/);});
